import React from 'react';
import { render } from '@testing-library/react';
import { ChakraProvider } from '@chakra-ui/react';
import { Logo } from './Logo';

jest.mock('./assets/logo.svg', () => 'app-logo.svg');

const mockPrefersReducedMotion = jest.fn(() => false);

jest.mock('@chakra-ui/react', () => {
  const actual = jest.requireActual('@chakra-ui/react');
  const ReactLib = require('react');
  return {
    ...actual,
    usePrefersReducedMotion: () => mockPrefersReducedMotion(),
    Image: ReactLib.forwardRef(
      ({ animation, src, ...rest }: any, ref: any) => (
        <img
          ref={ref}
          alt='logo'
          src={src}
          data-animation={animation || ''}
          {...rest}
        />
      )
    )
  };
});

describe('root Logo', () => {
  it('applies spin animation when motion is allowed', () => {
    mockPrefersReducedMotion.mockReturnValue(false);
    const { container } = render(
      <ChakraProvider>
        <Logo />
      </ChakraProvider>
    );

    const img = container.querySelector('img');
    expect(img).toHaveAttribute('src', 'app-logo.svg');
    expect(img?.getAttribute('data-animation')).toContain('infinite');
  });

  it('disables animation when reduced motion is preferred', () => {
    mockPrefersReducedMotion.mockReturnValue(true);
    const { container } = render(
      <ChakraProvider>
        <Logo />
      </ChakraProvider>
    );

    expect(container.querySelector('img')?.getAttribute('data-animation')).toBe(
      ''
    );
  });
});

import React from 'react';
import { render, screen } from '@testing-library/react';
import { ChakraProvider } from '@chakra-ui/react';
import { PopOver } from './PopOver';
import { useRadarState } from '@undp_sdg_ai_lab/undp-radar';

jest.mock('@undp_sdg_ai_lab/undp-radar', () => ({
  useRadarState: jest.fn(),
  useDataState: () => ({
    state: {
      keys: { titleKey: 'Ideas/Concepts/Examples' }
    }
  })
}));

const mockUseRadarState = useRadarState as jest.Mock;

const hoveredItem = {
  'Ideas/Concepts/Examples': 'Sensor Network',
  Description: 'IoT sensors for early warning',
  'Country of Implementation': 'Kenya',
  SDG: ['SDG 13', 'SDG 9'],
  'Status/Maturity': 'Production',
  'Disaster Cycle': 'Preparedness'
};

const renderPopOver = () =>
  render(
    <ChakraProvider>
      <PopOver />
    </ChakraProvider>
  );

describe('PopOver', () => {
  const originalMatchMedia = window.matchMedia;

  beforeEach(() => {
    Object.defineProperty(document.documentElement, 'ontouchstart', {
      configurable: true,
      value: undefined
    });
    window.matchMedia = jest.fn().mockImplementation(() => ({
      matches: false,
      media: '',
      onchange: null,
      addListener: jest.fn(),
      removeListener: jest.fn(),
      addEventListener: jest.fn(),
      removeEventListener: jest.fn(),
      dispatchEvent: jest.fn()
    }));
  });

  afterEach(() => {
    window.matchMedia = originalMatchMedia;
  });

  it('renders nothing without hover state', () => {
    mockUseRadarState.mockReturnValue({
      state: { hoveredItem: null, hoveredQuadOrHorizon: null }
    });

    const { container } = renderPopOver();
    expect(container).toBeEmptyDOMElement();
  });

  it('renders hovered item details on desktop', () => {
    mockUseRadarState.mockReturnValue({
      state: { hoveredItem, hoveredQuadOrHorizon: null }
    });

    renderPopOver();

    expect(screen.getByText('Sensor Network')).toBeInTheDocument();
    expect(
      screen.getByText('IoT sensors for early warning')
    ).toBeInTheDocument();
    expect(screen.getByText(/Kenya/)).toBeInTheDocument();
    expect(screen.getByText(/SDG 13, SDG 9/)).toBeInTheDocument();
    expect(screen.getByText(/Production/)).toBeInTheDocument();
    expect(screen.getByText(/Preparedness/)).toBeInTheDocument();
  });

  it('hides hovered item popover on mobile touch devices', () => {
    Object.defineProperty(document.documentElement, 'ontouchstart', {
      configurable: true,
      value: true
    });
    window.matchMedia = jest.fn().mockImplementation(() => ({
      matches: true,
      media: '',
      onchange: null,
      addListener: jest.fn(),
      removeListener: jest.fn(),
      addEventListener: jest.fn(),
      removeEventListener: jest.fn(),
      dispatchEvent: jest.fn()
    }));

    mockUseRadarState.mockReturnValue({
      state: { hoveredItem, hoveredQuadOrHorizon: null }
    });

    renderPopOver();
    expect(screen.queryByText('Sensor Network')).not.toBeInTheDocument();
  });

  it('renders single hovered quadrant or horizon', () => {
    mockUseRadarState.mockReturnValue({
      state: {
        hoveredItem: null,
        hoveredQuadOrHorizon: {
          title: 'Preparedness',
          description: 'Before the disaster'
        }
      }
    });

    renderPopOver();
    expect(screen.getByText('Preparedness')).toBeInTheDocument();
    expect(screen.getByText('Before the disaster')).toBeInTheDocument();
  });

  it('renders array of hovered quadrant or horizon entries', () => {
    mockUseRadarState.mockReturnValue({
      state: {
        hoveredItem: null,
        hoveredQuadOrHorizon: [
          { title: 'Idea', description: 'Early concepts' },
          { title: 'Validation', description: 'Testing ideas' }
        ]
      }
    });

    renderPopOver();
    expect(screen.getByText('Idea')).toBeInTheDocument();
    expect(screen.getByText('Early concepts')).toBeInTheDocument();
    expect(screen.getByText('Validation')).toBeInTheDocument();
    expect(screen.getByText('Testing ideas')).toBeInTheDocument();
  });
});

import React from 'react';
import { render, screen, fireEvent } from '@testing-library/react';
import { ChakraProvider } from '@chakra-ui/react';
import { MemoryRouter } from 'react-router-dom';
import { FilterDrawer } from './FilterDrawer';

jest.mock('./filter/CustomFilter', () => ({
  CustomFilter: () => <div data-testid='custom-filter'>CustomFilter</div>
}));

jest.mock('./tech/TechList', () => ({
  TechList: () => <div data-testid='tech-list'>TechList</div>
}));

jest.mock('components/radar/HowToPopup', () => ({
  HowToPopup: () => <div data-testid='how-to'>HowTo</div>
}));

jest.mock('@chakra-ui/react', () => {
  const actual = jest.requireActual('@chakra-ui/react');
  return {
    ...actual,
    Drawer: ({ children, isOpen }: any) =>
      isOpen ? <div data-testid='drawer'>{children}</div> : null,
    DrawerOverlay: ({ children }: any) => <div>{children}</div>,
    DrawerContent: ({ children }: any) => <div>{children}</div>,
    DrawerCloseButton: () => <button type='button'>close-drawer</button>,
    DrawerHeader: ({ children }: any) => <div>{children}</div>,
    useDisclosure: () => {
      const ReactActual = require('react');
      const [isOpen, setOpen] = ReactActual.useState(false);
      return {
        isOpen,
        onOpen: () => setOpen(true),
        onClose: () => setOpen(false)
      };
    }
  };
});

const mockPathname = jest.fn(() => '/radar');

jest.mock('react-router-dom', () => ({
  ...jest.requireActual('react-router-dom'),
  useLocation: () => ({ pathname: mockPathname() })
}));

describe('FilterDrawer', () => {
  beforeEach(() => {
    mockPathname.mockReturnValue('/radar');
  });

  it('renders title, howto, and opens options drawer', () => {
    render(
      <ChakraProvider>
        <MemoryRouter>
          <FilterDrawer />
        </MemoryRouter>
      </ChakraProvider>
    );

    expect(screen.getByTestId('how-to')).toBeInTheDocument();
    expect(screen.queryByTestId('drawer')).not.toBeInTheDocument();

    fireEvent.click(screen.getByRole('button', { name: /Filter/i }));
    expect(screen.getByTestId('drawer')).toBeInTheDocument();
    expect(screen.getByTestId('custom-filter')).toBeInTheDocument();
    expect(screen.getByTestId('tech-list')).toBeInTheDocument();
  });

  it('applies map page option-button class on map-view routes', () => {
    mockPathname.mockReturnValue('/map-view');
    const { container } = render(
      <ChakraProvider>
        <MemoryRouter>
          <FilterDrawer />
        </MemoryRouter>
      </ChakraProvider>
    );

    expect(
      container.querySelector('.option-button--mapPage')
    ).toBeInTheDocument();
  });
});

import React from 'react';
import { render, screen, fireEvent } from '@testing-library/react';
import { ChakraProvider } from '@chakra-ui/react';
import { LittleDrawer } from './LittleDrawer';
import { LittleDrawerIconButton } from './LittleDrawerIconButton';

describe('LittleDrawer', () => {
  it('toggles open state through the icon', async () => {
    const Icon = ({ onToggle, isOpen }: any) => (
      <button type='button' onClick={onToggle}>
        {isOpen ? 'close-drawer' : 'open-drawer'}
      </button>
    );

    render(
      <ChakraProvider>
        <LittleDrawer icon={Icon}>
          <div>drawer body</div>
        </LittleDrawer>
      </ChakraProvider>
    );

    expect(screen.getByText('open-drawer')).toBeInTheDocument();
    fireEvent.click(screen.getByText('open-drawer'));

    expect(await screen.findByText('close-drawer')).toBeInTheDocument();
    expect(screen.getByText('drawer body')).toBeInTheDocument();
    expect(document.querySelector('.littleDrawer-open')).toBeInTheDocument();
  });
});

describe('LittleDrawerIconButton', () => {
  it('renders server icon when closed and caret when open', () => {
    const { rerender } = render(
      <ChakraProvider>
        <LittleDrawerIconButton
          onToggle={jest.fn()}
          isOpen={false}
          type='SERVER'
          label='Servers'
        />
      </ChakraProvider>
    );

    expect(document.querySelector('.littleDrawerIconButton')).toBeInTheDocument();

    rerender(
      <ChakraProvider>
        <LittleDrawerIconButton
          onToggle={jest.fn()}
          isOpen
          type='SERVER'
          label='Servers'
        />
      </ChakraProvider>
    );

    expect(document.querySelector('.littleDrawerIconButton')).toBeInTheDocument();
  });

  it('renders cog icon and toggles on click', () => {
    const onToggle = jest.fn();
    render(
      <ChakraProvider>
        <LittleDrawerIconButton
          onToggle={onToggle}
          isOpen={false}
          type='COG'
          label='Settings'
        />
      </ChakraProvider>
    );

    fireEvent.click(screen.getByRole('button'));
    expect(onToggle).toHaveBeenCalled();
  });

  it('opens label popup on hover when drawer is closed', async () => {
    render(
      <ChakraProvider>
        <LittleDrawerIconButton
          onToggle={jest.fn()}
          isOpen={false}
          type='COG'
          label='Filters'
        />
      </ChakraProvider>
    );

    fireEvent.mouseOver(screen.getByRole('button'));
    expect(await screen.findByText('Filters')).toBeVisible();
  });

  it('does not toggle popup state while drawer is open', () => {
    render(
      <ChakraProvider>
        <LittleDrawerIconButton
          onToggle={jest.fn()}
          isOpen
          type='COG'
          label='Filters'
        />
      </ChakraProvider>
    );

    fireEvent.mouseOver(screen.getByRole('button'));
    // Popover stays closed: header may exist in DOM but should not be visible
    const label = screen.queryByText('Filters');
    if (label) {
      expect(label).not.toBeVisible();
    }
  });
});

