const renderHome = () =>
  render(
    <ChakraProvider>
      <MemoryRouter>
        <HomePage />
      </MemoryRouter>
    </ChakraProvider>
  );

describe('HomePage', () => {
  const originalLocation = window.location;

  beforeEach(() => {
    localStorage.clear();
    mockedApiRequest.mockReset();
    mockedIsSignedIn.mockReturnValue(false);
    mockedApiRequest.mockResolvedValue({ data: [] } as any);

    Object.defineProperty(window, 'location', {
      configurable: true,
      value: { ...originalLocation, href: '' }
    });
  });

  afterEach(() => {
    Object.defineProperty(window, 'location', {
      configurable: true,
      value: originalLocation
    });
  });

  it('renders the hero title and launch radar CTA', async () => {
    renderHome();

    expect(
      await screen.findByText(
        'Frontier Technology Radar for Disaster Risk Reduction'
      )
    ).toBeInTheDocument();
    expect(
      screen.getByRole('link', { name: /launch radar/i })
    ).toBeInTheDocument();
  });

  it('loads homepage sections from the API and caches them', async () => {
    mockedApiRequest.mockImplementation(async (path: string) => {
      switch (path) {
        case 'public/home-projects':
          return {
            data: [{ id: 'skip' }, { id: 'p1', name: 'Project One' }]
          } as any;
        case 'public/home-technologies':
          return { data: [{ id: 't1', name: 'Drones' }] } as any;
        case 'public/home-disaster-types':
          return { data: [{ id: 'd1', name: 'Flood' }] } as any;
        case 'public/home-help-needed':
          return { data: [{ id: 'r1', name: 'Urgent Flood' }] } as any;
        case 'public/home-recent-events':
          return { data: [{ id: 'e1', name: 'Event One' }] } as any;
        default:
          return { data: [] } as any;
      }
    });

    renderHome();

    expect(await screen.findByTestId('home-card-p1')).toHaveTextContent(
      'Project One'
    );
    expect(screen.getByTestId('home-card-mini-technologies-t1')).toHaveTextContent(
      'Drones'
    );
    expect(screen.getByTestId('home-card-mini-disasters-d1')).toHaveTextContent(
      'Flood'
    );
    expect(screen.getByTestId('recent-disasters')).toHaveTextContent(
      'Urgent Flood'
    );
    expect(screen.getByTestId('disaster-event-e1')).toHaveTextContent(
      'Event One'
    );

    expect(
      JSON.parse(localStorage.getItem('drr-projects-homepage') || '{}').data
    ).toEqual([{ id: 'p1', name: 'Project One' }]);
    expect(
      JSON.parse(localStorage.getItem('drr-technologies-homepage') || '{}').data
    ).toEqual([{ id: 't1', name: 'Drones' }]);
  });

  it('uses cached homepage data when the version matches', async () => {
    localStorage.setItem(
      'drr-projects-homepage',
      cache([{ id: 'cached-p', name: 'Cached Project' }])
    );
    localStorage.setItem(
      'drr-technologies-homepage',
      cache([{ id: 'cached-t', name: 'Cached Tech' }])
    );
    localStorage.setItem(
      'drr-disaster-types-homepage',
      cache([{ id: 'cached-d', name: 'Cached Disaster' }])
    );
    localStorage.setItem(
      'drr-recent-disasters',
      cache([{ id: 'cached-r', name: 'Cached Help' }])
    );
    localStorage.setItem(
      'drr-disaster-events',
      cache([{ id: 'cached-e', name: 'Cached Event' }])
    );

    renderHome();

    expect(await screen.findByTestId('home-card-cached-p')).toHaveTextContent(
      'Cached Project'
    );
    expect(screen.getByTestId('home-card-mini-technologies-cached-t')).toBeInTheDocument();
    expect(screen.getByTestId('home-card-mini-disasters-cached-d')).toBeInTheDocument();
    expect(screen.getByTestId('recent-disasters')).toHaveTextContent(
      'Cached Help'
    );
    expect(screen.getByTestId('disaster-event-cached-e')).toBeInTheDocument();
    expect(mockedApiRequest).not.toHaveBeenCalled();
  });

  it('shows an empty recent-disasters message when both lists are empty', async () => {
    renderHome();

    expect(await screen.findByText('No recent disasters')).toBeInTheDocument();
  });

  it('shows add-new-event when signed in', async () => {
    mockedIsSignedIn.mockReturnValue(true);
    renderHome();

    expect(
      await screen.findByRole('link', { name: /add new event/i })
    ).toHaveAttribute('href', '/disaster-events/new');
  });

  it('updates carousel description and navigates on item click', async () => {
    renderHome();

    fireEvent.click(await screen.findByText('carousel-next'));
    expect(
      await screen.findByText(
        /The Disasters Page has a list of disater types/i
      )
    ).toBeInTheDocument();

    fireEvent.click(screen.getByText('carousel-click'));
    expect(window.location.href).toBe('/#/technologies');
  });

  it('handles API failures without crashing', async () => {
    const errorSpy = jest.spyOn(console, 'error').mockImplementation(() => {});
    mockedApiRequest.mockRejectedValue(new Error('network'));

    renderHome();

    expect(await screen.findByText('No recent disasters')).toBeInTheDocument();
    expect(errorSpy).toHaveBeenCalled();
    errorSpy.mockRestore();
  });
});

import React from 'react';
import { render, screen, fireEvent } from '@testing-library/react';
import { MemoryRouter } from 'react-router-dom';
import { HomeCard } from './HomeCard';
import { HomeCardMini } from './HomeCardMini';
import { RecentDisasters } from './RecentDisasters';
import { RecentDisasterCardMini } from './RecentDisasterCardMini';
import { RadarContext } from 'navigation/context';

const mockSetCurrentProject = jest.fn();

const renderWithContext = (ui: React.ReactElement) =>
  render(
    <MemoryRouter>
      <RadarContext.Provider
        value={{ setCurrentProject: mockSetCurrentProject } as any}
      >
        {ui}
      </RadarContext.Provider>
    </MemoryRouter>
  );

describe('home page cards', () => {
  beforeEach(() => {
    mockSetCurrentProject.mockClear();
  });

  it('renders HomeCard and sets current project on click', () => {
    const project = {
      uuid: 'p1',
      name: 'Home Project',
      img_url: 'home.png'
    } as any;

    renderWithContext(
      <HomeCard project={project} fallbackImage='fallback.png' />
    );

    expect(screen.getByText('Home Project')).toBeInTheDocument();
    fireEvent.click(screen.getByRole('link'));
    expect(mockSetCurrentProject).toHaveBeenCalledWith(project);
    expect(screen.getByRole('link')).toHaveAttribute('href', '/projects/p1');
  });

  it('falls back image and title fields on HomeCard', () => {
    const project = {
      'Ideas/Concepts/Examples': 'Legacy Idea',
      'Image Url': 'legacy.png'
    } as any;

    renderWithContext(
      <HomeCard project={project} fallbackImage='fallback.png' />
    );

    expect(screen.getByText('Legacy Idea')).toBeInTheDocument();
    const img = screen.getByAltText('Default Image');
    fireEvent.error(img);
    expect(img).toHaveAttribute('src', 'fallback.png');
  });

  it('renders HomeCardMini with type route and summary', () => {
    const project = {
      slug: 'drones',
      name: 'Drones',
      img_url: 'drones.png',
      summary: 'Aerial mapping'
    } as any;

    renderWithContext(
      <HomeCardMini project={project} type='technologies' />
    );

    expect(screen.getByText('Drones')).toBeInTheDocument();
    expect(screen.getByText('Aerial mapping')).toBeInTheDocument();
    expect(screen.getByRole('link')).toHaveAttribute(
      'href',
      '/technologies/drones'
    );
    fireEvent.click(screen.getByRole('link'));
    expect(mockSetCurrentProject).toHaveBeenCalledWith(project);
  });

  it('uses fallback image on HomeCardMini error', () => {
    const project = {
      slug: 'ai',
      title: 'AI',
      'Image Url': 'broken.png'
    } as any;

    renderWithContext(<HomeCardMini project={project} type='technologies' />);

    const img = screen.getByAltText('Default Image');
    fireEvent.error(img);
    expect(img).toHaveAttribute(
      'src',
      expect.stringContaining('fallback-image.png')
    );
  });

  it('lists recent disasters with links', () => {
    renderWithContext(
      <RecentDisasters
        recentDisasters={[
          {
            uuid: 'd1',
            id: 1,
            title: 'Cyclone',
            summary: 'Help needed'
          }
        ]}
      />
    );

    expect(screen.getByText('Cyclone')).toBeInTheDocument();
    expect(screen.getByText('Help needed')).toBeInTheDocument();
    expect(screen.getByRole('link')).toHaveAttribute(
      'href',
      '/disaster-events/d1'
    );
  });

  it('renders RecentDisasterCardMini and truncates long summaries', () => {
    const longSummary = 'y'.repeat(160);
    renderWithContext(
      <RecentDisasterCardMini
        recentDisaster={{
          uuid: 'e1',
          id: 1,
          title: 'Drought Event',
          summary: longSummary,
          img_url: 'drought.png'
        }}
      />
    );

    expect(screen.getByText('Drought Event')).toBeInTheDocument();
    expect(screen.getByText(/\.\.\./)).toBeInTheDocument();
    expect(screen.getByRole('link')).toHaveAttribute(
      'href',
      '/disaster-events/e1'
    );
  });

  it('omits summary on RecentDisasterCardMini when missing', () => {
    renderWithContext(
      <RecentDisasterCardMini
        recentDisaster={{
          uuid: 'e2',
          id: 2,
          title: 'Short Event',
          summary: '',
          img_url: 'img.png'
        }}
      />
    );

    expect(screen.getByText('Short Event')).toBeInTheDocument();
    expect(screen.queryByText(/\.\.\./)).not.toBeInTheDocument();
  });
});

