      );
    });
    errorSpy.mockRestore();
  });

  it('loads an existing technology for edit and updates related projects', async () => {
    mockedApiRequest.mockResolvedValue({} as any);
    mockPathname = '/technologies/drones/edit';
    localStorage.setItem(
