import React from 'react';
import { render, screen, fireEvent, waitFor, cleanup } from '@testing-library/react';
import { ChakraProvider } from '@chakra-ui/react';
import { RadarMapView } from './RadarMapView';
import { RadarContext } from 'navigation/context';

const mockSetTechFilter = jest.fn();
const mockSetFilteredBlips = jest.fn();
const mockSetBlipsMerged = jest.fn();
const mockSetRadarStateValues = jest.fn();
const mockSetFiltered = jest.fn();

let mockBlips: any[] = [];
let mockFilteredBlips: any[] = [];
let mockTechFilters: string[] = [];
let mockIsFiltered = false;

jest.mock('react-leaflet', () => ({
  MapContainer: ({ children }: any) => (
    <div data-testid='leaflet-map'>{children}</div>
  ),
  TileLayer: () => <div data-testid='tile-layer' />,
  CircleMarker: ({ children, center }: any) => (
    <div data-testid='circle-marker' data-center={JSON.stringify(center)}>
      {children}
    </div>
  ),
  Popup: ({ children, eventHandlers }: any) => (
    <div data-testid='popup'>
      <button type='button' onClick={() => eventHandlers?.add?.()}>
        open-popup
      </button>
      <button type='button' onClick={() => eventHandlers?.remove?.()}>
        close-popup
      </button>
      {children}
    </div>
  ),
  Tooltip: ({ children }: any) => <div data-testid='tooltip'>{children}</div>
}));

jest.mock('geos-major', () => ({
  country: () => ({ latitude: -18, longitude: 178 })
}));

jest.mock('./helpers', () => ({
  mapBlips: (blips: any[]) => {
    const map = new Map();
    blips.forEach((b) => {
      const countries = b['Country of Implementation'] || [];
      countries.forEach((c: string) => {
        if (c === 'Global') return;
        if (!map.has(c)) map.set(c, []);
        map.get(c).push(b);
      });
    });
    return map;
  },
  BlipPopOver: ({ projects }: any) => (
    <div data-testid='blip-popover'>{projects.length} projects</div>
  )
}));

jest.mock('./ProjectSlider', () => ({
  ProjectSlider: () => <div data-testid='project-slider' />
}));

jest.mock('@undp_sdg_ai_lab/undp-radar', () => ({
  useRadarState: () => ({
    state: {
      get blips() {
        return mockBlips;
      },
      get filteredBlips() {
        return mockFilteredBlips;
      },
      get techFilters() {
        return mockTechFilters;
      },
      get isFiltered() {
        return mockIsFiltered;
      }
    },
    actions: { setTechFilter: mockSetTechFilter },
    processes: { setFilteredBlips: mockSetFilteredBlips }
  })
}));

const sampleBlips = [
  {
    'Ideas/Concepts/Examples': 'Flood Mapper',
    'Disaster Cycle': 'response',
    'Country of Implementation': ['Fiji', 'Global'],
    Technology: ['Drones']
  },
  {
    'Ideas/Concepts/Examples': 'Flood Mapper',
    'Disaster Cycle': 'preparedness',
    'Country of Implementation': ['Fiji'],
    Technology: ['AI']
  },
  {
    'Ideas/Concepts/Examples': 'Drought Tool',
    'Disaster Cycle': 'mitigation',
    'Country of Implementation': ['Kenya'],
    Technology: ['GIS']
  }
];

const renderMap = () =>
  render(
    <ChakraProvider>
      <RadarContext.Provider
        value={
          {
            filteredValues: { parameters: {} },
            setBlipsMerged: mockSetBlipsMerged,
            setRadarStateValues: mockSetRadarStateValues,
            setFiltered: mockSetFiltered
          } as any
        }
      >
        <RadarMapView />
      </RadarContext.Provider>
    </ChakraProvider>
  );

describe('RadarMapView', () => {
  beforeEach(() => {
    mockBlips = sampleBlips;
    mockFilteredBlips = sampleBlips;
    mockTechFilters = [];
    mockIsFiltered = false;
    mockSetTechFilter.mockClear();
    mockSetFilteredBlips.mockClear();
    mockSetBlipsMerged.mockClear();
    mockSetRadarStateValues.mockClear();
    mockSetFiltered.mockClear();
  });

  it('renders the map container and markers', async () => {
    renderMap();

    expect(screen.getByTestId('map')).toBeInTheDocument();
    expect(screen.getByTestId('leaflet-map')).toBeInTheDocument();
    await waitFor(() => {
      expect(screen.getAllByTestId('circle-marker').length).toBeGreaterThan(0);
    });
    expect(mockSetTechFilter).toHaveBeenCalledWith([]);
    expect(mockSetRadarStateValues).toHaveBeenCalledWith({});
    expect(mockSetBlipsMerged).toHaveBeenCalledWith(true);
  });

  it('merges disaster cycles for duplicate ideas into display blips', async () => {
    renderMap();

    await waitFor(() => {
      // After merge, Flood Mapper is one blip; Fiji and Kenya each get a marker
      expect(screen.getByText('Fiji')).toBeInTheDocument();
      expect(screen.getByText('Kenya')).toBeInTheDocument();
      expect(mockSetBlipsMerged).toHaveBeenCalledWith(true);
    });
  });

  it('opens and closes country popups', async () => {
    renderMap();

    await waitFor(() => {
      expect(screen.getAllByTestId('popup').length).toBeGreaterThan(0);
    });

    fireEvent.click(screen.getAllByText('open-popup')[0]);
    expect(screen.getAllByTestId('blip-popover')[0]).toBeInTheDocument();

    fireEvent.click(screen.getAllByText('close-popup')[0]);
  });

  it('clears filters when isFiltered on mount and restores on unmount', () => {
    mockIsFiltered = true;
    renderMap();

    expect(mockSetFilteredBlips).toHaveBeenCalledWith(false, sampleBlips);

    cleanup();

    expect(mockSetFilteredBlips).toHaveBeenCalledWith(true, sampleBlips);
    expect(mockSetFiltered).toHaveBeenCalledWith(false);
  });

  it('applies tech filters to blips', async () => {
    mockTechFilters = ['drones'];
    mockFilteredBlips = sampleBlips;
    renderMap();

    await waitFor(() => {
      expect(mockSetBlipsMerged).toHaveBeenCalled();
    });
  });
});

import React from 'react';
import { render, screen, fireEvent } from '@testing-library/react';
import { ChakraProvider } from '@chakra-ui/react';
import { RadarContext } from 'navigation/context';
import { mapBlips, BlipPopOver } from './helpers';
import { ProjectSlider } from './ProjectSlider';

jest.mock('pages/search/SearchView', () => ({
  SearchView: ({ techContent }: any) => (
    <div data-testid='search-view'>
      {techContent['Ideas/Concepts/Examples'] || techContent.title}
    </div>
  ),
  __esModule: true,
  default: ({ techContent }: any) => (
    <div data-testid='search-view'>
      {techContent['Ideas/Concepts/Examples'] || techContent.title}
    </div>
  )
}));

jest.mock('geos-major', () => ({
  country: (code: string | undefined) => {
    if (code === 'FJ') {
      return { continent: 'Oceania', subContinent: 'Melanesia' };
    }
    if (code === 'KE') {
      return { continent: 'Africa', subContinent: 'Eastern Africa' };
    }
    if (code === 'JM') {
      return { continent: 'Americas', subContinent: 'Caribbean' };
    }
    return null;
  }
}));

const sampleBlips = [
  {
    id: 1,
    'Ideas/Concepts/Examples': 'Fiji Project',
    Description: 'Short desc',
    'Country of Implementation': ['Fiji', 'Global'],
    SDG: ['SDG 13'],
    'Status/Maturity': 'production',
    'Disaster Cycle': 'response',
    'Un Host Organisation': 'UNDP',
    'Image Url': 'fiji.png'
  },
  {
    id: 2,
    'Ideas/Concepts/Examples': 'Kenya Project',
    Description: 'x'.repeat(160),
    'Country of Implementation': ['Kenya'],
    SDG: ['SDG 1'],
    'Status/Maturity': 'prototype',
    'Disaster Cycle': 'preparedness',
    'Un Host Organisation': 'UNEP',
    'Image Url': 'kenya.png'
  },
  {
    id: 3,
    'Ideas/Concepts/Examples': 'Typo Project',
    Description: 'fixes typos',
    'Country of Implementation': [
      'Jamacia',
      'Democratic Republic of the Congo',
      'Micronesi'
    ],
    SDG: ['SDG 5'],
    'Status/Maturity': 'validation',
    'Disaster Cycle': 'mitigation',
    'Un Host Organisation': 'UNDP',
    'Image Url': 'jm.png'
  },
  {
    id: 4,
    'Ideas/Concepts/Examples': 'Second Fiji',
    Description: 'another fiji project',
    'Country of Implementation': ['Fiji'],
    SDG: ['SDG 9'],
    'Status/Maturity': 'production',
    'Disaster Cycle': 'response',
    'Un Host Organisation': 'UNDP',
    'Image Url': 'fiji2.png'
  }
] as any[];

const MapBlipsHarness = ({ blips }: { blips: any[] }) => {
  const map = mapBlips(blips);
  return (
    <div>
      <span data-testid='size'>{map.size}</span>
      <span data-testid='keys'>{Array.from(map.keys()).join('|')}</span>
      <span data-testid='fiji-count'>{map.get('Fiji')?.length || 0}</span>
    </div>
  );
};

const renderWithFilters = (
  ui: React.ReactElement,
  filteredValues: any = { parameters: {} }
) =>
  render(
    <ChakraProvider>
      <RadarContext.Provider value={{ filteredValues } as any}>
        {ui}
      </RadarContext.Provider>
    </ChakraProvider>
  );

describe('mapBlips', () => {
  it('groups blips by country and skips Global', () => {
    renderWithFilters(<MapBlipsHarness blips={sampleBlips} />);

    expect(screen.getByTestId('size')).toHaveTextContent('5');
    expect(screen.getByTestId('keys').textContent).toContain('Fiji');
    expect(screen.getByTestId('keys').textContent).toContain('Kenya');
    // Typo countries are remapped in the blip array but keyed with the original labels
    expect(screen.getByTestId('keys').textContent).toContain('Jamacia');
    expect(screen.getByTestId('fiji-count')).toHaveTextContent('2');
  });

  it('filters by selected country labels', () => {
    renderWithFilters(<MapBlipsHarness blips={sampleBlips} />, {
      parameters: {
        Country: [{ label: 'Kenya', value: 'kenya' }]
      }
    });

    expect(screen.getByTestId('size')).toHaveTextContent('1');
    expect(screen.getByTestId('keys')).toHaveTextContent('Kenya');
  });

  it('filters by region labels', () => {
    renderWithFilters(<MapBlipsHarness blips={sampleBlips} />, {
      parameters: {
        Region: [{ label: 'Oceania', value: 'oceania' }]
      }
    });

    expect(screen.getByTestId('keys').textContent).toContain('Fiji');
    expect(screen.getByTestId('keys').textContent).not.toContain('Kenya');
  });

  it('filters by subregion labels', () => {
    renderWithFilters(<MapBlipsHarness blips={sampleBlips} />, {
      parameters: {
        'Sub Region': [{ label: 'Eastern Africa', value: 'eastern africa' }]
      }
    });

    expect(screen.getByTestId('keys')).toHaveTextContent('Kenya');
    expect(screen.getByTestId('size')).toHaveTextContent('1');
  });
});

describe('BlipPopOver', () => {
  const projects = [
    {
      id: 1,
      'Ideas/Concepts/Examples': 'Alpha',
      Description: 'Alpha desc',
      'Country of Implementation': ['Fiji'],
      SDG: ['SDG 13'],
      'Status/Maturity': 'production',
      'Disaster Cycle': 'response'
    },
    {
      id: 2,
      'Ideas/Concepts/Examples': 'Beta',
      Description: 'Beta desc',
      'Country of Implementation': ['Kenya'],
      SDG: ['SDG 1'],
      'Status/Maturity': 'prototype',
      'Disaster Cycle': 'preparedness'
    }
  ];

  it('lists multiple projects until one is selected', () => {
    const setPopupClosed = jest.fn();
    const setCountryProjects = jest.fn();

    renderWithFilters(
      <BlipPopOver
        projects={projects}
        setPopupClosed={setPopupClosed}
        popupState='open'
        setCountryProjects={setCountryProjects}
      />
    );

    expect(screen.getByText('Alpha')).toBeInTheDocument();
    expect(screen.getByText('Beta')).toBeInTheDocument();

