>;

const makeProjects = (count: number) =>
  Array.from({ length: count }, (_, i) => ({
    id: `p${i + 1}`,
    name: `Project ${i + 1}`,
    title: `Project ${i + 1}`,
    description: `desc ${i + 1}`,
