    process.env.SUPABASE_URL = 'https://example.supabase.co';
    process.env.SUPABASE_SECRET_KEY = 'test-secret';
    process.env.ALLOWED_ORIGINS = `${ALLOWED_ORIGIN},http://localhost:3000`;

    mockClient = createMockClient({
      tables: {
